-- Every dated, mapped event of organized violence worldwide since 1989 -- 386K events with death tolls.
-- Auto-generated by scripts/gen_evidence_pages.py: 385,918 rows > 100k, so this is a BOUNDED pre-aggregate (parquet-safe by construction), not select *.
select year("DATE_START") as year, count(*) as records
from THE_LIBRARY.CRIME_SECURITY.ARMED_CONFLICT_EVENTS
where "DATE_START" is not null
group by 1
order by 1
